INSERT INTO item VALUES (1187,'Abjuration','Staff',NULL,'No','Strong abjuration','13','65,000 gp',NULL,'Craft Staff, dismissal, dispel magic, lesser globe of invulnerability, resist energy, repulsion, shield',NULL,NULL,'\n      <div topic=\"Abjuration\" level=\"8\"><p><b>Abjuration:</b> Usually carved from the heartwood of an ancient oak or other large tree, this staff allows use of the following spells:</p><ul>\n <li> <i>Shield</i> (1 charge)</li>\n <li> <i>Resist energy</i> (1 charge)</li>\n <li> <i>Dispel magic</i> (1 charge)</li>\n <li> <i>Lesser globe of invulnerability</i> (2 charges)</li>\n <li> <i>Dismissal</i> (2 charges)</li>\n <li> <i>Repulsion</i> (3 charges)</li>\n</ul><p>Strong abjuration; CL 13th; Craft Staff, <i>dismissal</i>,  <i>dispel magic</i>,  <i>lesser globe of invulnerability</i>,  <i>resist energy</i>,  <i>repulsion</i>,  <i>shield</i>; Price 65,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1188,'Charming','Staff',NULL,'No','Moderate enchantment','8','16,500 gp',NULL,'Craft Staff, Charm person, charm monster',NULL,NULL,'\n      <div topic=\"Charming\" level=\"8\"><p><b>Charming:</b> Made of twisting wood ornately shaped and carved, this staff allows use of the following spells:</p><ul>\n <li> <i>Charm person</i> (1 charge)</li>\n <li> <i>Charm monster</i> (2 charges)</li>\n</ul><p>Moderate enchantment; CL 8th; Craft Staff, <i>Charm person</i>,  <i>charm monster</i>; Price 16,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1189,'Conjuration','Staff',NULL,'No','Strong conjuration','13','65,000 gp',NULL,'Craft Staff, cloudkill, stinking cloud, summon monster VI, summon swarm, unseen servant',NULL,NULL,'\n      <div topic=\"Conjuration\" level=\"8\"><p><b>Conjuration:</b> This staff is usually made of ash or walnut and bears ornate carvings of many different kinds of creatures. It allows use of the following spells:</p><ul>\n <li> <i>Unseen servant</i> (1 charge)</li>\n <li> <i>Summon swarm</i> (1 charge)</li>\n <li> <i>Stinking cloud</i> (1 charge)</li>\n <li> <i>Minor creation</i> (2 charges)</li>\n <li> <i>Cloudkill</i> (2 charges)</li>\n <li> <i>Summon monster VI</i> (3 charges)</li>\n</ul><p>Strong conjuration; CL 13th; Craft Staff, <i>cloudkill</i>,  <i>stinking cloud</i>,  <i>summon monster VI</i>,  <i>summon swarm</i>,  <i>unseen servant</i>; Price 65,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1190,'Defense','Staff',NULL,'No','Strong abjuration','15','58,250 gp',NULL,'Craft Staff, shield, shield of faith, shield of law, shield other, creator must be lawful',NULL,NULL,'\n      <div topic=\"Defense\" level=\"8\"><p><b>Defense:</b> The <i>staff of defense</i> is a simple-looking staff that throbs with power when held defensively. It allows use of the following spells:</p><ul>\n <li> <i>Shield</i> (1 charge)</li>\n <li> <i>Shield of faith</i> (1 charge)</li>\n <li> <i>Shield other</i> (1 charge)</li>\n <li> <i>Shield of law</i> (3 charges)</li>\n</ul><p>Strong abjuration; CL 15th; Craft Staff, <i>shield</i>,  <i>shield of faith</i>,  <i>shield of law</i>,  <i>shield other</i>, creator must be lawful; Price 58,250 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1191,'Divination','Staff',NULL,'No','Strong divination','13','73,500 gp',NULL,'Craft Staff, detect secret doors, locate creature, locate object, prying eyes, tongues, true seeing',NULL,NULL,'\n      <div topic=\"Divination\" level=\"8\"><p><b>Divination:</b> Made from a supple length of willow, often with a forked tip, this staff allows use of the following spells:</p><ul>\n <li> <i>Detect secret doors</i> (1 charge)</li>\n <li> <i>Locate object</i> (1 charge)</li>\n <li> <i>Tongues</i> (1 charge)</li>\n <li> <i>Locate creature</i> (2 charges)</li>\n <li> <i>Prying eyes</i> (2 charges)</li>\n <li> <i>True seeing</i> (3 charges)</li>\n</ul><p>Strong divination; CL 13th; Craft Staff, <i>detect secret doors</i>, <i>locate creature</i>,  <i>locate object</i>,  <i>prying eyes</i>,  <i>tongues</i>, <i>true seeing</i>; Price 73,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1192,'Earth and Stone','Staff',NULL,'No','Moderate transmutation','11','80,500 gp',NULL,'Craft Staff, move earth, passwall',NULL,NULL,'\n      <div topic=\"Earth and Stone\" level=\"8\"><p><b>Earth and Stone:</b> This staff is topped with a fist-sized emerald that gleams with smoldering power. It allows the use of the following spells:</p><ul>\n <li> <i>Passwall</i> (1 charge)</li>\n <li> <i>Move earth</i> (1 charge)</li>\n</ul><p>Moderate transmutation; CL 11th; Craft Staff, <i>move earth</i>,  <i>passwall</i>; Price 80,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1193,'Enchantment','Staff',NULL,'No','Strong enchantment','13','65,000 gp',NULL,'Craft Staff, crushing despair, mass suggestion, mind fog, sleep, suggestion, hideous laughter',NULL,NULL,'\n      <div topic=\"Enchantment\" level=\"8\"><p><b>Enchantment:</b> Often made from applewood and topped with a clear crystal, this staff allows use of the following spells:</p><ul>\n <li> <i>Sleep</i> (1 charge)</li>\n <li> <i>Hideous laughter</i> (1 charge)</li>\n <li> <i>Suggestion</i> (1 charge)</li>\n <li> <i>Crushing despair</i> (2 charges)</li>\n <li> <i>Mind fog</i> (2 charges)</li>\n <li> <i>Suggestion</i>,  <i>mass</i> (3 charges)</li>\n</ul><p>Strong enchantment; CL 13th; Craft Staff, c<i>rushing despair</i>,  <i>mass suggestion</i>,  <i>mind fog</i>,  <i>sleep</i>,  <i>suggestion</i>,  <i>hideous laughter</i>; Price 65,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1194,'Evocation','Staff',NULL,'No','Strong evocation','13','65,000 gp',NULL,'Craft Staff, chain lightning, fireball, ice storm, magic missile, shatter, wall of force',NULL,NULL,'\n      <div topic=\"Evocation\" level=\"8\"><p><b>Evocation:</b> Usually very smooth and carved from hickory, willow, or yew, this staff allows use of the following spells:</p><ul>\n <li> <i>Magic missile</i> (1 charge)</li>\n <li> <i>Shatter</i> (1 charge)</li>\n <li> <i>Fireball</i> (1 charge)</li>\n <li> <i>Ice storm</i> (2 charges)</li>\n <li> <i>Wall of force</i> (2 charges)</li>\n <li> <i>Chain lightning</i> (3 charges)</li>\n</ul><p>Strong evocation; CL 13th; Craft Staff,  <i>chain lightning</i>,  <i>fireball</i>,  <i>ice storm</i>,  <i>magic missile</i>, <i>shatter</i>,  <i>wall of force</i>; Price 65,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1195,'Fire','Staff',NULL,'No','Moderate evocation','8','17,750 gp',NULL,'Craft Staff, Burning hands, fireball, wall of fire',NULL,NULL,'\n      <div topic=\"Fire\" level=\"8\"><p><b>Fire:</b> Crafted from bronzewood with brass bindings, this staff allows use of the following spells:</p><ul>\n <li> <i>Burning hands</i> (1 charge)</li>\n <li> <i>Fireball</i> (1 charge)</li>\n <li> <i>Wall of fire</i> (2 charges)</li>\n</ul><p>Moderate evocation; CL 8th; Craft Staff, <i>Burning hands</i>,  <i>fireball</i>,  <i>wall of fire</i>; Price 17,750 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1196,'Frost','Staff',NULL,'No','Moderate evocation','10','56,250 gp',NULL,'Craft Staff, cone of cold, ice storm, wall of ice',NULL,NULL,'\n      <div topic=\"Frost\" level=\"8\"><p><b>Frost:</b> Tipped on either end with a glistening diamond, this rune-covered staff allows use of the following spells:</p><ul>\n <li> <i>Ice storm</i> (1 charge)</li>\n <li> <i>Wall of ice</i> (1 charge)</li>\n <li> <i>Cone of cold</i> (2 charge)</li>\n</ul><p>Moderate evocation; CL 10th; Craft Staff,  <i>cone of cold</i>, <i>ice storm</i>,  <i>wall of ice</i>; Price 56,250 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
INSERT INTO item VALUES (1197,'Healing','Staff',NULL,'No','Moderate conjuration','8','27,750 gp',NULL,'Craft Staff, cure serious wounds, lesser restoration, remove blindness/deafness, remove disease',NULL,NULL,'\n      <div topic=\"Healing\" level=\"8\"><p><b>Healing:</b> This white ash staff, with inlaid silver runes, allows use of the following spells:</p><ul>\n <li> <i>Lesser restoration</i> (1 charge)</li>\n <li> <i>Cure serious wounds</i> (1 charge)</li>\n <li> <i>Remove blindness/deafness</i> (2 charges)</li>\n <li> <i>Remove disease</i> (3 charges)</li>\n</ul><p>Moderate conjuration; CL 8th; Craft Staff, <i>cure serious wounds</i>,  <i>lesser restoration</i>,  <i>remove blindness/deafness</i>,  <i>remove disease</i>; Price 27,750 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIV');
